"""Realtime dashboard mode for `harness analyse --watch`.

Polls the target JSONL file's mtime every N seconds. When the mtime changes,
re-runs the parse → analyse → render pipeline via the `_render_once` helper.
The rendered HTML carries a `<meta http-equiv="refresh">` tag so the browser
tab reloads automatically.

No new runtime dependencies — stdlib only.
"""

from __future__ import annotations

import os
import sys
import time
from collections.abc import Callable
from pathlib import Path

# Type alias for the renderer dependency-injection seam used by tests.
RenderFn = Callable[..., list[Path]]


def watch_loop(
    *,
    target: Path,
    out_dir: Path,
    format: str,
    skip_synthesis: bool,
    model: str,
    interval_seconds: int,
    render_fn: RenderFn | None = None,
    mtime_fn: Callable[[Path], float] | None = None,
    sleep_fn: Callable[[float], None] | None = None,
    max_ticks: int | None = None,
    log: Callable[[str], None] | None = None,
) -> int:
    """Poll-and-render loop. Returns 0 on clean exit (user Ctrl+C), 1 on error.

    Args:
        target: JSONL session file to watch.
        out_dir: Output directory for rendered HTML.
        format: Output format (passed through to the renderer).
        skip_synthesis: Force-skip narrative synthesis (recommended under --watch
            because the LLM call is too slow for a 5s tick).
        model: Model to use for synthesis (unused when skip_synthesis is true).
        interval_seconds: Polling interval (clamped to [1, 60]).
        render_fn: Renderer to invoke when mtime changes. Defaults to
            `harness.commands.analyse._render_once`. Tests inject a fake.
        mtime_fn: Function returning the target's mtime. Defaults to
            `os.path.getmtime`. Tests inject a fake.
        sleep_fn: Sleep function. Defaults to `time.sleep`. Tests inject a noop.
        max_ticks: Optional cap on polling iterations (test affordance).
        log: Optional log callback for status messages.
    """
    if render_fn is None:
        from harness.commands.analyse import _render_once
        render_fn = _render_once
    if mtime_fn is None:
        mtime_fn = lambda p: os.path.getmtime(str(p))  # noqa: E731
    if sleep_fn is None:
        sleep_fn = time.sleep
    if log is None:
        log = lambda s: print(s, file=sys.stderr)  # noqa: E731

    interval = max(1, min(60, interval_seconds))

    if not target.exists():
        log(f"watch: target {target} does not exist")
        return 1

    last_mtime: float = -1.0
    tick = 0
    log(f"watch: polling {target} every {interval}s; press Ctrl+C to stop")

    try:
        while True:
            try:
                current_mtime = mtime_fn(target)
            except (FileNotFoundError, OSError) as exc:
                log(f"watch: mtime read failed: {exc}; retrying")
                sleep_fn(interval)
                tick += 1
                if max_ticks is not None and tick >= max_ticks:
                    return 0
                continue

            if current_mtime != last_mtime:
                last_mtime = current_mtime
                try:
                    written = render_fn(
                        target=target,
                        out_dir=out_dir,
                        format=format,
                        skip_synthesis=skip_synthesis,
                        model=model,
                        auto_refresh_seconds=interval,
                        verbose=False,
                    )
                    log(f"watch: rendered {len(written)} file(s) at tick {tick + 1}")
                except Exception as exc:  # render errors should not crash the loop
                    log(f"watch: render failed: {exc}")

            tick += 1
            if max_ticks is not None and tick >= max_ticks:
                return 0

            sleep_fn(interval)
    except KeyboardInterrupt:
        log("watch: stopped")
        return 0
